using Servicio.RetazoMarket.Business.DTOs.MovimientoMaterial;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class MovimientoMaterialService:IMovimientoMaterialService {private readonly IMovimientoMaterialDataService _movimientos;private readonly IMaterialDataService _materiales;public MovimientoMaterialService(IMovimientoMaterialDataService movimientos,IMaterialDataService materiales)=>(_movimientos,_materiales)=(movimientos,materiales);public async Task<MovimientoMaterialResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _movimientos.ObtenerPorIdAsync(id,ct);return m is null?null:MovimientoMaterialBusinessMapper.ToResponse(m);}public async Task<IReadOnlyList<MovimientoMaterialResponse>> ObtenerPorMaterialAsync(int id,CancellationToken ct=default)=>(await _movimientos.ObtenerPorMaterialAsync(id,ct)).Select(m=>MovimientoMaterialBusinessMapper.ToResponse(m)).ToList();public async Task<DataPagedResult<MovimientoMaterialResponse>> BuscarAsync(MovimientoMaterialFiltroRequest f,CancellationToken ct=default){var e=MovimientoMaterialValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _movimientos.BuscarAsync(new MovimientoMaterialFiltroDataModel{id_material=f.id_material,tipo_movimiento=f.tipo_movimiento?.Trim().ToUpperInvariant(),motivo=f.motivo?.Trim(),fecha_desde_utc=f.fecha_desde_utc,fecha_hasta_utc=f.fecha_hasta_utc,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(m=>MovimientoMaterialBusinessMapper.ToResponse(m)).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<MovimientoMaterialResponse> CrearAsync(CrearMovimientoMaterialRequest r,CancellationToken ct=default){var e=MovimientoMaterialValidator.ValidarCreacion(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);var material=await _materiales.ObtenerPorIdAsync(r.id_material,ct)??throw new ValidationException("El material no existe.");var tipo=r.tipo_movimiento.Trim().ToUpperInvariant();var stock=MovimientoMaterialValidator.CalcularStock(material.stock_actual,tipo,r.cantidad);if(stock<0)throw new ValidationException("El movimiento produciría stock negativo.");var creado=await _movimientos.CrearConActualizacionStockAsync(MovimientoMaterialBusinessMapper.ToDataModel(r),stock,ct)??throw new ValidationException("No se pudo actualizar el material.");return MovimientoMaterialBusinessMapper.ToResponse(creado,stock);}}
